with enriched as (select e.*, p.amount as order_amount, p.status as order_status, p.discount from payments e left join orders p on e.order_id = p.id), enriched_payments as (select e.*, p.channel, p.shipping_fee, p.discount as order_discount from enriched e left join orders p on e.order_id = p.id), deduped as (select *, row_number() over (partition by status, order_id order by order_amount nulls first, id) as latest_rank from enriched_payments qualify latest_rank = 1) select case when amount >= 1390 then 'PREMIUM' else 'STANDARD' end as amount_tier, order_id, order_status, count(case when status = 'SUCCESS' then 1 end) as success_count, count(*) as event_count, count(case when channel = 'partner' then 1 end) as partner_count, percentile_approx(order_discount, array(0.25, 0.5, 0.75)) as order_discount_quartiles, size(collect_set(channel)) as num_channels, round(avg(amount), 2) as avg_amount from deduped group by case when amount >= 1390 then 'PREMIUM' else 'STANDARD' end, order_id, order_status
